 // Payslip HowTo (visible content mirroring HowTo JSON-LD)
 'payslip.howto.title': 'So simulieren Sie die Lohnabrechnung eines neuen Grenzgängers',
 'payslip.howto.intro': 'Schritt-für-Schritt-Anleitung zur Simulation der Lohnabrechnung eines neuen Grenzgängers für 2026 mit Tessiner Quellensteuer, AHV/BVG-Abzügen und Netto-Vergleich CH vs. IT.',
 'payslip.howto.step1.name': 'Bruttojahresgehalt in CHF eingeben',
 'payslip.howto.step1.text': 'Geben Sie das Bruttojahresgehalt in Schweizer Franken (CHF) gemäss Arbeitsvertrag ein. Der Simulator berechnet das Monatsbrutto durch Division durch 13 (13. Monatslohn inbegriffen).',
 'payslip.howto.step2.name': 'Alter, Zivilstand und Kinder angeben',
 'payslip.howto.step2.text': 'Wählen Sie Alter (bestimmt den BVG-Satz), Zivilstand (Tarif A ledig oder B verheiratet) und Anzahl der unterhaltsberechtigten Kinder. Jedes Kind reduziert die Quellensteuer um etwa einen Prozentpunkt.',
 'payslip.howto.step3.name': 'Wohnzone wählen (innerhalb oder ausserhalb 20 km)',
 'payslip.howto.step3.text': 'Geben Sie an, ob Sie innerhalb von 20 km zur Schweizer Grenze wohnen oder weiter entfernt. Nach dem neuen Abkommen 2026 zahlen neue Grenzgänger innerhalb 20 km 80% Quellensteuer in der Schweiz und italienische IRPEF mit €10\'000 Freibetrag, ausserhalb 20 km beträgt die Schweizer Quellensteuer 100%.',
 'payslip.howto.step4.name': 'Schweizer Sozialabzüge prüfen',
 'payslip.howto.step4.text': 'Überprüfen Sie die Aufschlüsselung der obligatorischen Beiträge: AHV/IV/EO (5,3%), ALV Arbeitslosenversicherung (1,1%), UVG Nichtberufsunfallversicherung, Krankentaggeld IJM und BVG (2. Säule, altersgestaffelter Satz 25-65).',
 'payslip.howto.step5.name': 'Quellensteuer-Simulation anzeigen',
 'payslip.howto.step5.text': 'Sehen Sie die nach dem Tessiner Tarif A/B/C/H 2026 berechnete Quellensteuer mit Prozentsatz und CHF-Betrag auf Monatsbasis.',
 'payslip.howto.step6.name': 'Schweizer Netto mit italienischem Netto in Euro vergleichen',
 'payslip.howto.step6.text': 'Vergleichen Sie das Schweizer Netto mit dem italienischen unter Berücksichtigung von IRPEF und Steuergutschrift: das ist der Betrag, der einem neuen Grenzgänger 2026 tatsächlich bleibt.',
 'payslip.howto.step7.name': 'Lohnabrechnung als PDF exportieren',
 'payslip.howto.step7.text': 'Laden Sie die Zusammenfassung der Simulation als PDF mit allen Abzügen AHV, ALV, UVG, IJM, BVG und Quellensteuer herunter: nützlich zum Vergleich mit der echten Lohnabrechnung des Arbeitgebers.',

 // Payslip FAQ (visible content mirroring FAQPage JSON-LD)
 'payslip.faq.title': 'Häufige Fragen zur Lohnabrechnung des Grenzgängers',
 'payslip.faq.q1.q': 'Was ist das neue Grenzgängerabkommen 2026?',
 'payslip.faq.q1.a': 'Das neue Steuerabkommen Italien-Schweiz (seit 2024 in Kraft und 2026 vollständig angewandt) unterscheidet zwischen "alten" und "neuen" Grenzgängern. Neue Grenzgänger (ab 17.07.2023 angestellt), die innerhalb 20 km zur Grenze wohnen, zahlen 80% Quellensteuer in der Schweiz und erklären das Einkommen in Italien mit €10\'000 Freibetrag und Steuergutschrift. Ausserhalb 20 km beträgt die Schweizer Quellensteuer 100%.',
 'payslip.faq.q2.q': 'Wann gilt man als "neuer Grenzgänger"?',
 'payslip.faq.q2.a': 'Man gilt als neuer Grenzgänger, wenn der Schweizer Arbeitsvertrag ab dem 17. Juli 2023 unterzeichnet wurde. Wer vorher angestellt wurde, bleibt bis 31. Dezember 2033 (Übergangszeit) "alter Grenzgänger", mit Besteuerung nur in der Schweiz zu 100% und Rückläufern an die italienischen Grenzgemeinden.',
 'payslip.faq.q3.q': 'Wie wird die Quellensteuer im Tessin 2026 berechnet?',
 'payslip.faq.q3.a': 'Die Tessiner Quellensteuer wird vom Arbeitgeber nach dem kantonalen Tarif angewendet: A (ledig, ohne Kinder), B (verheiratet, Einzelverdiener), C (verheiratet, Doppelverdiener) und H (Alleinerziehende). Der Satz hängt vom monatlichen Bruttoeinkommen ab und reicht von ca. 2% (CHF 3\'000/Monat) bis 16% (über CHF 15\'000/Monat). Jedes Kind reduziert den Satz um etwa einen Prozentpunkt.',
 'payslip.faq.q4.q': 'Was ändert sich, wenn ich weiter als 20 km von der Schweizer Grenze wohne?',
 'payslip.faq.q4.a': 'Neue Grenzgänger, die weiter als 20 km von der Schweizer Grenze wohnen, verlieren den Grenzgänger-Steuerstatus nach dem neuen Abkommen: Sie zahlen 100% Quellensteuer in der Schweiz (wie Ansässige ohne Rücklauf) und erklären das Einkommen in Italien mit voller Steuergutschrift, um Doppelbesteuerung zu vermeiden. Der Freibetrag von 10\'000 € gilt in diesem Fall nicht.',
 'payslip.faq.q5.q': 'Sind AHV- und BVG-Beiträge in Italien abzugsfähig?',
 'payslip.faq.q5.a': 'Ja. Die obligatorischen Schweizer Sozialversicherungsbeiträge AHV/IV/EO (5,3%) und BVG (2. Säule), die in der Schweiz einbehalten werden, sind vom IRPEF-steuerpflichtigen Einkommen neuer Grenzgänger in der italienischen Steuererklärung abzugsfähig und senken damit die italienische Bemessungsgrundlage. Bewahren Sie den jährlichen Schweizer Lohnausweis für Ihren Steuerberater auf.',
 'payslip.faq.q6.q': 'Kann ich den Simulator auch mit B-Ausweis nutzen?',
 'payslip.faq.q6.a': 'Ja. Der Lohnabrechnungs-Simulator berechnet die Sozialabzüge (AHV, ALV, UVG, IJM, BVG) und die Tessiner Quellensteuer: Dies sind die gleichen Positionen wie auf der Lohnabrechnung eines B-Ausweis-Inhabers, der im Tessin arbeitet. Mit B-Ausweis gilt jedoch nicht das Sonderregime für Grenzgänger (italienische Steuergutschrift): Das CHF-Netto ist Ihr tatsächliches Netto. Für einen G-vs-B-Vergleich verwenden Sie den speziellen Rechner.',
 'payslip.faq.q7.q': 'Ist die Quellensteuer endgültig oder kann ich über die TDR etwas zurückholen?',
 'payslip.faq.q7.a': 'Die Tessiner Quellensteuer kann über die TDR (Tariffa Doganale Ridotta) bis zum 31. März des Folgejahres korrigiert werden. Zugelassene Abzüge umfassen Fahrkosten (max CHF 3\'200), Mahlzeiten ausser Haus, Säule-3a-Beiträge (max CHF 7\'258 im Jahr 2026), Krankheitskosten und Alimente. Die Rückerstattung wird direkt auf Ihr Bankkonto überwiesen.',
 'payslip.faq.q8.q': 'Beinhaltet der Simulator den 13. Monatslohn und die Familienzulagen?',
 'payslip.faq.q8.a': 'Das eingegebene Bruttojahresgehalt enthält bereits den 13. Monatslohn (durch 13 geteilt, um das Monatsbrutto zu erhalten). Die kantonalen Familienzulagen (ca. CHF 200-300 pro Monat und Kind im Tessin) sind in der Simulation nicht enthalten, da sie nicht den Sozialabzügen und der Quellensteuer unterliegen: Addieren Sie sie zum berechneten Netto.',

