 'salaryCompare.disclaimer': 'Daten basierend auf BFS (Bundesamt für Statistik), SECO-Statistiken und Marktschätzungen 2024-2025. Die tatsächlichen Gehälter variieren je nach Unternehmen, Qualifikation und individueller Verhandlung.',
