 'salaryCompare.cantonAll': 'Schweiz (nationaler Durchschnitt)',
 'salaryCompare.cantonNetTitle': 'Geschätzter Nettolohn nach Kanton (CH)',
 'salaryCompare.cantonNetDesc': 'Geschätzter Schweizer Nettolohn, falls dasselbe Profil in einem anderen Kanton arbeiten würde, basierend auf den BFS-Lohnniveaus (Bundesamt für Statistik) nach Grossregion.',
 'salaryCompare.cantonNetDisclaimer': 'Hinweis: Dies ist eine SCHÄTZUNG, keine offizielle Steuerberechnung. Der Bruttolohn pro Kanton spiegelt das regionale Durchschnittslohnniveau (BFS-Daten) wider; die Nettoberechnung verwendet den realen Steuerbelastungssatz des jeweiligen Kantonshauptorts (offizielle ESTV-Daten, alleinstehende Person ohne Kinder, Steuerjahr 2024) und bildet damit die tatsächlichen kantonalen/kommunalen Steuerunterschiede ab — berücksichtigt aber nicht Ihre persönliche Situation (Zivilstand, Kinder, Abzüge, genaue Wohngemeinde). Für eine genaue Steuerschätzung konsultieren Sie den offiziellen Rechner Ihres Arbeitskantons.',
 'salaryCompare.cantonNetColGross': 'Geschätzter Bruttolohn',
 'salaryCompare.cantonNetColNet': 'Geschätzter Nettolohn',
 'salaryCompare.cantonNetComuneNote': 'Suchen Sie eine Schätzung für Ihre Wohngemeinde in Italien?',
 'salaryCompare.cantonNetComuneLink': 'Karte der Grenzgemeinden nutzen',
 'salaryCompare.salaryRange': 'Gehaltsspanne',
 'salaryCompare.median': 'Median',
 'salaryCompare.professions': 'Berufe',
 'salaryCompare.totalSectors': 'analysierte Branchen',
 'salaryCompare.totalProfessions': 'analysierte Berufe',
 'salaryCompare.methodology': 'Methodik & Datenquellen',
 'salaryCompare.methodologyText1': 'Die Gehaltsdaten basieren auf der Schweizerischen Lohnstrukturerhebung (LSE) des Bundesamtes für Statistik (BFS), ergänzt durch SECO-Daten, Jobportale (jobs.ch, Michael Page) und Marktschätzungen 2024-2025. Die Schweizer Gehälter sind spezifisch für den Kanton Tessin angepasst, der durchschnittlich 10-15% unter dem nationalen Median liegt.',
 'salaryCompare.methodologyText2': 'Für Italien stammen die Daten von ISTAT, Glassdoor und Indeed, mit Fokus auf die Grenzregionen (Lombardei, Piemont, Ligurien). Die Nettoberechnungen beinhalten Schweizer Sozialabzüge (AHV/IV/EO 5.3%, ALV 1.1%, UVG 0.7%, KTG 0.8%, BVG-Durchschnitt), Tessiner Quellensteuer und für Italien IRPEF 2026, regionale Zuschläge und INPS-Beiträge.',
 'salaryCompare.methodologyText3': 'Die Gehaltsspannen (Minimum-Median-Maximum) spiegeln Variabilität nach Unternehmensgrösse, spezifischer Erfahrung, Zertifizierungen und Verhandlungsgeschick wider. Die Kaufkraftparität (KKP) wird mit Faktor 0.65 berechnet, unter Berücksichtigung der deutlich höheren Lebenshaltungskosten in der Schweiz.',
 'salaryCompare.faqTitle': 'Häufige Fragen zu Gehältern',
 'salaryCompare.faq1Q': 'Wie hoch sind die Durchschnittsgehälter im Tessin 2026?',
 'salaryCompare.faq1A': 'Das Mediangehalt im Tessin reicht von CHF 48.000-55.000 für Einstiegspositionen im Handel/Gastronomie bis CHF 125.000-200.000+ für Senior-Positionen in Finanz, Pharma und IT. Das Tessin hat die niedrigsten Gehälter der Schweiz, sie bleiben aber 2-3 mal höher als in Italien.',
 'salaryCompare.faq2Q': 'Wie viel verdient ein Grenzgänger-Informatiker in der Schweiz?',
 'salaryCompare.faq2A': 'Ein Grenzgänger-Softwareentwickler im Tessin verdient durchschnittlich CHF 72.000 brutto als Junior (0-3 Jahre), CHF 95.000 als Mid-Level (3-7 Jahre) und CHF 125.000+ als Senior (7+ Jahre). Nach Quellensteuer und Sozialabzügen beträgt das Netto Junior ca. CHF 58.000 und Senior ca. CHF 93.000.',
 'salaryCompare.faq3Q': 'Lohnt sich die Arbeit als Grenzgänger finanziell?',
 'salaryCompare.faq3A': 'In den meisten Branchen verdienen Grenzgänger 100% bis 200% mehr als bei vergleichbarer Arbeit in Italien, auch unter Berücksichtigung von Transportkosten und Steuern. Unter Einbeziehung der Kaufkraftparität (KKP) reduziert sich der Vorteil auf 30-80%, da die Lebenshaltungskosten in der Schweiz deutlich höher sind.',
 'salaryCompare.faq4Q': 'Wie werden Grenzgänger-Gehälter besteuert?',
 'salaryCompare.faq4A': 'Grenzgänger mit Bewilligung G zahlen Quellensteuer im Kanton Tessin (3% bis 18% je nach Einkommen), plus Schweizer Sozialabgaben (AHV, ALV, UVG, KTG, BVG). Mit dem Neuen Abkommen 2026 zahlen neue Grenzgänger 80% der Steuern in der Schweiz und einen Anteil in Italien mit einem Freibetrag von €10.000.',
 'salaryCompare.faq5Q': 'Welche Branchen zahlen im Tessin am meisten?',
 'salaryCompare.faq5A': 'Die bestbezahlten Branchen im Tessin sind: Finanz & Banken (Senior-Median CHF 145.000), Pharma (CHF 135.000), Beratung (CHF 150.000) und IT & Software (CHF 125.000). Gastronomie und Handel bieten die niedrigsten Gehälter (CHF 68.000-72.000 Senior).',
