 'jobBoard.apply': 'Bewerben',
 'jobBoard.applicationIntentConsent': 'Mit «Bewerben» stimmst du zu, dass wir dein Interesse an dieser Stelle speichern. Wir erfassen den Klick und notwendige technische Daten; dies bedeutet nicht, dass die Bewerbung abgeschlossen wurde.',
 'jobBoard.applicationIntentDetails': 'Was der Klick auf «Bewerben» speichert',
 'jobBoard.assisted.title': 'Möchtest du diese Bewerbung delegieren?',
 'jobBoard.assisted.body': 'Sende uns deinen Lebenslauf und die nötigen Angaben: Wir bereiten die Bewerbung für diese Stelle automatisch vor, schicken sie dir zur Freigabe und reichen sie selbst ein, per E-Mail oder im Portal des Unternehmens.',
 'jobBoard.assisted.copy.time_saved.title': 'Zeit bei deiner Bewerbung sparen',
 'jobBoard.assisted.copy.time_saved.body': 'Sende uns deinen Lebenslauf und die nötigen Angaben: Wir bereiten die Bewerbung für diese Stelle vor, schicken sie dir zur Freigabe und reichen sie ein, wenn es der Prozess des Unternehmens zulässt.',
 'jobBoard.assisted.copy.portal_relief.title': 'Möchtest du das Unternehmensportal nicht selbst verwalten?',
 'jobBoard.assisted.copy.portal_relief.body': 'Du sendest uns deinen Lebenslauf und die nötigen Angaben; wir bereiten die Bewerbung für diese Stelle vor, schicken sie dir zur Freigabe und reichen sie per E-Mail oder im Unternehmensportal ein, wenn möglich.',
 'jobBoard.assisted.copy.handled_for_you.title': 'Sollen wir uns darum kümmern?',
 'jobBoard.assisted.copy.handled_for_you.body': 'Überlass uns diese Bewerbung: Wir erstellen die Unterlagen aus deinem Lebenslauf, schicken sie dir zur Freigabe und reichen sie ein, wenn es der Prozess des Unternehmens zulässt.',
 'jobBoard.assisted.stepsLabel': 'So funktioniert es',
 'jobBoard.assisted.step1': 'Du sendest uns deinen Lebenslauf und die nötigen Angaben',
 'jobBoard.assisted.step2': 'Wir bereiten die Bewerbung für diese Stelle vor',
 'jobBoard.assisted.step3': 'Wir schicken sie dir zur Freigabe und reichen sie dann ein',
 'jobBoard.assisted.transparency': 'Wir garantieren keine Antwort, kein Vorstellungsgespräch und keine Einstellung. Frontaliere Ticino ist nicht mit dem Unternehmen verbunden; der Dienst gilt nur für diese Stelle.',
 'jobBoard.assisted.externalCta': 'Selbst bewerben, kostenlos',
 'jobBoard.assisted.externalCtaVideo': 'Selbst bewerben, kostenlos mit einem kurzen Video',
 'jobBoard.assisted.paidCta': 'Einreichung delegieren — 1,99 €',
 'jobBoard.assisted.paidLoading': 'Zahlung wird geöffnet…',
 'jobBoard.assisted.priceNote': 'Einmalige Zahlung · kein Abonnement',
 'jobBoard.concierge.eyebrow': 'Automatisierte Jobsuche',
 'jobBoard.concierge.title': 'Automatisiere deine Jobsuche in der Schweiz',
 'jobBoard.concierge.description': '30 Tage lang sucht der Service nach Stellen, die zu deinem Profil passen, erstellt passende Lebensläufe, Anschreiben und Antworten und organisiert deine Bewerbungen. Eine gezielte, rechtzeitige Bewerbung kann deine Chancen auf ein Vorstellungsgespräch verbessern; Antworten und Einstellungen sind nicht garantiert.',
 'jobBoard.concierge.duration': '30 Tage ab Zahlungsbestätigung',
 'jobBoard.concierge.quota': 'Bis zu 10 angenommene Stellen',
 'jobBoard.concierge.noRenewal': 'Einmalige Zahlung · keine Verlängerung',
 'jobBoard.concierge.disclosure': 'Kostenpflichtiger Dienst: 39,99 €. Die Automatisierung hilft dir, effizienter Bewerbungen zu senden, garantiert aber keine passenden Stellen, gesendeten Bewerbungen, Antworten, Gespräche oder Einstellungen.',
 'jobBoard.concierge.start': 'Dienst aktivieren',
 'jobBoard.concierge.resumePayment': 'Zahlung fortsetzen',
 'jobBoard.concierge.paymentTitle': 'Zahlung abschliessen',
 'jobBoard.concierge.paymentError': 'Die Zahlung konnte nicht abgeschlossen werden. Prüfe deine Angaben oder versuche es erneut.',
 'jobBoard.concierge.offerLink': 'Du suchst mehrere Stellen? Automatisiere deine Jobsuche',
 'jobBoard.concierge.offerLinkHint': 'Wir finden passende Stellen, bereiten Bewerbungen vor und senden sie nach deinem Einverständnis.',
 'jobBoard.concierge.landingBadge': 'Automatisierung + persönliche Kontrolle für 30 Tage',
 'jobBoard.concierge.priceNote': 'einmalige Zahlung · keine Verlängerung',
 'jobBoard.concierge.howItWorksTitle': 'Von der Suche bis zum Versand – automatisiert und kontrolliert',
 'jobBoard.concierge.howItWorksIntro': 'Du gibst Lebenslauf und Präferenzen an. Das System sucht, bereitet Bewerbungen vor und hält dich auf dem Laufenden.',
 'jobBoard.concierge.step1Title': 'Lebenslauf und Präferenzen',
 'jobBoard.concierge.step1Text': 'Sende uns deinen Lebenslauf und nenne Rollen, Orte und wichtige Einschränkungen.',
 'jobBoard.concierge.step2Title': 'Automatisierte Suche',
 'jobBoard.concierge.step2Text': 'Wir analysieren passende Stellen und schlagen dir die relevantesten Möglichkeiten vor.',
 'jobBoard.concierge.step3Title': 'Bewerbung nach Mass',
 'jobBoard.concierge.step3Text': 'Wir erstellen Lebenslauf, Anschreiben und Antworten passend zur Stelle und zu deiner Erfahrung.',
 'jobBoard.concierge.step4Title': 'Bestätigen und senden',
 'jobBoard.concierge.step4Text': 'Gib dein Einverständnis; wenn du den Entwurf nicht innerhalb von 12 Stunden änderst, kann er automatisch über den Service versendet werden.',
 'jobBoard.concierge.benefitsTitle': 'Gezieltere Bewerbungen, mehr Zeit für Gespräche',
 'jobBoard.concierge.benefitsIntro': 'Wir reduzieren die wiederholte Sucharbeit, damit du dich auf die passenden Stellen konzentrieren kannst. Besser zugeschnittene, rechtzeitige Bewerbungen können deine Chancen auf ein Gespräch verbessern.',
 'jobBoard.concierge.benefitMatchingTitle': 'Automatisierte Suche und Auswahl',
 'jobBoard.concierge.benefitMatchingText': 'Wir filtern verfügbare Möglichkeiten nach Profil, Rolle und Präferenzen.',
 'jobBoard.concierge.benefitTailoredTitle': 'Persönliche Unterlagen',
 'jobBoard.concierge.benefitTailoredText': 'Wir erstellen passende Lebensläufe, Anschreiben und Antworten nur aus deinen Profilinformationen.',
 'jobBoard.concierge.benefitApprovalTitle': 'Kontrolle und Überblick',
 'jobBoard.concierge.benefitApprovalText': 'Bestätige Stellen, prüfe die Bewerbung und erhalte Updates zum Fortschritt.',
 'jobBoard.concierge.includedTitle': 'Das ist im Service enthalten',
 'jobBoard.concierge.includedIntro': 'Ein klar definierter Zeitraum und ein transparenter Preis, damit du schneller suchen und dich bewerben kannst.',
 'jobBoard.concierge.included30': 'Tage aktiver Service',
 'jobBoard.concierge.included10': 'maximal angenommene Stellen',
 'jobBoard.concierge.includedPrice': 'Gesamtpreis, keine automatische Verlängerung',
 'jobBoard.concierge.clarityTitle': 'Transparente Automatisierung, zuerst deine Zustimmung',
 'jobBoard.concierge.clarityText': 'Das Ziel ist, dir schnellere und passendere Bewerbungen zu ermöglichen. Eine gezielte Bewerbung kann deine Chancen auf ein Gespräch verbessern, aber kein Service kann ein Ergebnis versprechen.',
 'jobBoard.concierge.clarityApproval': 'Du entscheidest, welche Stellen du annimmst, und kannst den Entwurf vor dem Versand ändern.',
 'jobBoard.concierge.clarityNoRenewal': 'Nach deinem Einverständnis kann der Versand automatisch erfolgen, wenn du den Entwurf 12 Stunden lang nicht änderst.',
 'jobBoard.concierge.finalTitle': 'Möchtest du schneller die passenden Möglichkeiten erreichen?',
 'jobBoard.concierge.finalText': 'Aktiviere den Service: Wir automatisieren die Suche und erstellen gezielte Bewerbungen, damit du mehr Zeit für Gespräche hast.',
 'jobBoard.concierge.seoTitle': 'Automatisiere deine Jobsuche in der Schweiz',
 'jobBoard.concierge.seoDescription': 'Automatisiere deine Jobsuche in der Schweiz: Wir finden passende Stellen und erstellen Bewerbungen nach Mass. Das kann deine Chancen verbessern.',
 'jobBoard.concierge.seoKeywords': 'Jobsuche Schweiz automatisieren, automatisierte Jobsuche, Bewerbung nach Mass, automatische Bewerbung, Arbeit in der Schweiz finden, Vorstellungsgespräch',
