 'jobBoard.assisted.uploadError': `Upload fehlgeschlagen. Versuche es mit einer PDF-, DOC- oder DOCX-Datei erneut oder schreibe an ${PUBLIC_CONTACT_EMAIL} mit deinem Lebenslauf im Anhang.`,
 'jobBoard.assisted.review.title': "Prüfe deine Bewerbung",
 'jobBoard.assisted.review.stale': "Das ist eine frühere Version deiner Bewerbung. Öffne den Link aus der neuesten E-Mail.",
 'jobBoard.assisted.review.waiting.drafting': "Ich bereite deine Bewerbung vor: Du bekommst eine E-Mail, sobald sie zur Prüfung bereit ist.",
 'jobBoard.assisted.review.waiting.regenerating': "Ich bereite eine neue Version mit deinen Hinweisen vor und melde mich, sobald sie bereit ist.",
 'jobBoard.assisted.review.waiting.owner_review': "Die Bewerbung wird abschliessend geprüft: Gleich bekommst du die E-Mail zur Freigabe.",
 'jobBoard.assisted.review.waiting.submitting': "Du hast freigegeben: Deine Bewerbung ist in der Versandwarteschlange und geht in wenigen Minuten raus. Du kannst diese Seite schließen, ich schreibe dir, sobald sie verschickt ist.",
 'jobBoard.assisted.review.submitted': "Deine Bewerbung wurde gesendet. Viel Erfolg!",
 'jobBoard.assisted.review.submittedWhatsapp': "Für diese Stelle nimmt das Unternehmen Bewerbungen nur über WhatsApp entgegen: Ich habe dir den Link und die Schritte per E-Mail geschickt. Öffne den Link auf dem Handy, sende die vorbereitete Nachricht ab und beantworte die Fragen des Assistenten im Chat. Viel Erfolg!",
 'jobBoard.assisted.review.openWhatsapp': "Bewerbung auf WhatsApp öffnen",
 'jobBoard.assisted.review.kept.title': "Deine Unterlagen",
 'jobBoard.assisted.review.kept.introSent': "Das sind die Dateien, die mit deiner Bewerbung versendet wurden. Lade sie herunter, um sie aufzubewahren.",
 'jobBoard.assisted.review.kept.introPrepared': "Das sind das Motivationsschreiben und der Lebenslauf deiner Bewerbung. Lade sie herunter, um sie aufzubewahren.",
 'jobBoard.assisted.review.kept.introWhatsapp': "Das sind das für diese Bewerbung vorbereitete Motivationsschreiben und dein Lebenslauf: Verwende sie im Chat, wenn der Assistent des Unternehmens nach einem Schreiben oder einem Lebenslauf fragt.",
 'jobBoard.assisted.review.kept.introWhatsappChoice': "Das sind das Motivationsschreiben und die Lebensläufe für diese Bewerbung. Fragt der Assistent des Unternehmens im Chat nach deinem Lebenslauf, entscheidest du, welchen du schickst: Wir schlagen den angepassten Lebenslauf vor (unten hervorgehoben), du kannst aber auch deinen ursprünglichen Lebenslauf senden.",
 'jobBoard.assisted.review.kept.suggested': "Unser Vorschlag",
 'jobBoard.assisted.review.kept.retention': "Deine Daten, auch diese Unterlagen, werden spätestens 90 Tage nach dem Versand gelöscht: Lade sie vorher herunter.",
 'jobBoard.assisted.review.kept.letter': "Motivationsschreiben (PDF)",
 'jobBoard.assisted.review.kept.cvTailored': "Angepasster Lebenslauf (PDF)",
 'jobBoard.assisted.review.kept.cvOriginal': "Dein ursprünglicher Lebenslauf",
