 'jobBoard.assisted.review.photoAdviceRecommended': "In der Deutschschweiz ist ein Foto im Lebenslauf üblich, aber nicht obligatorisch. Wenn Sie möchten, fügen Sie eines hinzu: neutraler Hintergrund, JPG oder PNG, höchstens 2 MB.",
