 'renovation.updated2026': 'Aktualisiert gemäss Haushaltsgesetz 2026',
 'renovation.propertyType': 'Immobilientyp',
 'renovation.primaCasa': 'Erstwohnung',
 'renovation.secondaCasa': 'Zweitwohnung',
 'renovation.secondaCasaNote': 'Für Zweitwohnungen sinkt der Renovierungsbonus von 50% auf 36% mit einem Maximum von €48.000 (Haushaltsgesetz 2026).',
 'renovation.capienzaTitle': 'Wichtig für Grenzgänger: Steuerkapazität',
 'renovation.capienzaWarning': 'Renovierungsabzüge reduzieren Ihre italienische IRPEF-Steuerschuld. Wenn Sie Grenzgänger sind und Ihr Schweizer Einkommen nicht der IRPEF unterliegt (altes Abkommen), können Sie den Bonus nur nutzen, wenn Sie andere italienische Steuern zum Ausgleich haben: Mieteinnahmen, Grundsteuern (IMU), Katastereinkommen oder andere in Italien deklarierte Einkünfte.',
 'renovation.faqTitle': 'FAQ — Grenzgänger & Wohnungsboni',
 'renovation.faq.frontaliereBonusAccess.q': 'Können Grenzgänger italienische Renovierungsboni nutzen?',
 'renovation.faq.frontaliereBonusAccess.a': 'Ja, vorausgesetzt Sie haben "Steuerkapazität" (capienza fiscale) — also italienische Steuern (IRPEF), gegen die der Bonus verrechnet werden kann. Die Ausgaben werden in Abschnitt RP der Steuererklärung (Modello Redditi PF) eingetragen. Neue Grenzgänger (ab 2024), die Schweizer Einkommen in Italien deklarieren, haben in der Regel genügend Kapazität. Grenzgänger mit altem Abkommen benötigen andere steuerpflichtige italienische Einkünfte.',
 'renovation.faq.capienzaFiscale.q': 'Was ist "Steuerkapazität" und warum ist sie wichtig?',
 'renovation.faq.capienzaFiscale.a': '"Steuerkapazität" (capienza fiscale) ist die Brutto-IRPEF, die Sie schulden. Renovierungsabzüge reduzieren diese Steuer direkt. Wenn Ihre Brutto-IRPEF null ist (z.B. Grenzgänger mit altem Abkommen ohne andere italienische Einkünfte), können Sie nicht vom Abzug profitieren. Quellen: Mieteinnahmen, Katastereinkommen, Einkommen aus Selbstständigkeit, andere in Italien deklarierte Einkünfte.',
 'renovation.faq.quadroRP.q': 'Wie werden Renovierungskosten deklariert?',
 'renovation.faq.quadroRP.a': 'Die Ausgaben werden in Abschnitt RP (Abschnitt III-A) des Modello Redditi PF eingetragen: Beginn der Arbeiten, Steuernummer des Begünstigten, Ausgabenbetrag, Anzahl der Raten. Die Erklärung muss jedes Jahr für die gesamte Ratendauer (10 Jahre für die meisten Boni) eingereicht werden. Rechnungen und spezielle Überweisungen (bonifici parlanti) aufbewahren.',
 'renovation.faq.excessDeduction.q': 'Was passiert, wenn der jährliche Abzug die geschuldeten Steuern übersteigt?',
 'renovation.faq.excessDeduction.a': 'Der überschüssige Teil des jährlichen Abzugs kann weder erstattet noch vorgetragen werden. Deshalb ist eine ausreichende Steuerkapazität jedes Jahr entscheidend. Beispiel: Wenn Ihr jährlicher Abzug €2.400 beträgt, aber Ihre Brutto-IRPEF nur €1.000, verlieren Sie €1.400 Abzug für dieses Jahr.',
 'renovation.faq.vecchioAccordo.q': 'Grenzgänger mit altem Abkommen: Können sie diese Boni nutzen?',
 'renovation.faq.vecchioAccordo.a': 'Ja, aber mit einer wichtigen Bedingung. Vor dem 17.07.2023 eingestellte Arbeitnehmer ("altes Abkommen") deklarieren kein Schweizer Einkommen in Italien, ihre Arbeits-IRPEF ist also null. Sie können Boni dennoch nutzen, wenn sie Immobilien mit Katastereinkommen besitzen, Mieten erhalten oder andere italienische Einkünfte haben. Grundsteuern (IMU, cedolare secca) generieren ebenfalls Kapazität. Eine Simulation mit dem Steuerberater lohnt sich.',
 'renovation.bonus.ristrutturazione': 'Renovierungsbonus',
 'renovation.bonusDesc.ristrutturazione': 'Abzug für Gebäuderenovierung. Erstwohnung: 50% bis €96.000. Zweitwohnung: 36% bis €48.000.',
 'renovation.bonus.ecobonus': 'Öko-Bonus 65%',
 'renovation.bonusDesc.ecobonus': '65% Abzug für Energiesparmassnahmen (Dämmung, Fenster, Heizkessel).',
 'renovation.bonus.sismabonus': 'Erdbebenbonus 50-85%',
 'renovation.bonusDesc.sismabonus': 'Abzug für Erdbebensicherheit, von 50% bis 85% je nach Klasseverbesserung.',
 'renovation.bonus.mobili': 'Möbelbonus 50%',
 'renovation.bonusDesc.mobili': '50% Abzug für Möbel und Grossgeräte (Klasse A+), max €5.000.',
 'renovation.bonus.verdi': 'Grünbonus 36%',
 'renovation.bonusDesc.verdi': '36% Abzug für Landschaftsgestaltung, Gärten, Terrassen, Bewässerungsanlagen.',
 'renovation.cat.energySaving': 'Energiesparen',
 'renovation.catDesc.energySaving': 'Wärmedämmung, Fensteraustausch, Solarpanels, Wärmepumpen.',
 'renovation.cat.maintenance': 'Ausserordentliche Instandhaltung',
 'renovation.catDesc.maintenance': 'Bad-/Küchenrenovierung, Elektro-/Sanitärinstallationen, Dach.',
 'renovation.cat.luxuryUpgrade': 'Luxus-Verbesserungen',
 'renovation.catDesc.luxuryUpgrade': 'Erweiterungen, Neubauten, Luxus-Interventionen. Begrenzte Absetzbarkeit in der CH.',
 'renovation.cat.environmental': 'Umweltschutz',
