 'tfr.noTfrTitle': 'In der Schweiz gibt es kein TFR (Abfindung)!',
 'tfr.noTfrText': 'Anders als in Italien gibt es in der Schweiz keine Abfindung (TFR/Trattamento di Fine Rapporto). Bei Beendigung des Arbeitsverhältnisses wird kein Betrag vom Arbeitgeber zurückgelegt. Das Äquivalent ist die 2. Säule (BVG/LPP): ein obligatorischer Beitrag zur beruflichen Vorsorge, verwaltet von Pensionskassen und als Rente oder Kapital bei der Pensionierung zurückgezahlt.',
