 'tfr.tableLppTotal': 'BVG gesamt',
 'tfr.keyDifferencesTitle': 'Hauptunterschiede: TFR vs BVG',
 'tfr.diffAccessTitle': 'Zugang zu den Mitteln',
 'tfr.diffAccessTfr': 'Auszahlung bei Ende des Arbeitsverhältnisses. Vorschuss möglich (70%) für Eigenheim oder Arztkosten.',
 'tfr.diffAccessLpp': 'Verfügbar bei Pensionierung (65). Vorbezug für Eigenheim, Selbstständigkeit oder endgültiges Verlassen der Schweiz.',
 'tfr.diffTaxTitle': 'Besteuerung',
 'tfr.diffTaxTfr': 'Separate Besteuerung mit Durchschnittssatz der letzten 5 Jahre. Generell günstig.',
 'tfr.diffTaxLpp': 'Für Grenzgänger mit Rückkehr nach Italien: reduzierte Schweizer Quellensteuer auf Kapital, dann italienische Besteuerung mit 5% (Rente) oder separat (Kapital).',
 'tfr.diffReturnTitle': 'Rendite',
 'tfr.diffReturnTfr': 'Feste Aufwertung: 1,5% + 75% ISTAT-Inflation. Geringe Realrendite bei niedriger Inflation.',
 'tfr.diffReturnLpp': 'BVG-Minimum 1,25% (2026). Beste Pensionskassen wenden bis zu 3-4% an. Das Kapital wird an den Finanzmärkten investiert.',
 'tfr.diffFrontaliereTitle': 'Was passiert für Grenzgänger',
 'tfr.diffFrontaliereText1': 'Grenzgänger mit Ausweis G sammeln Schweizer BVG (2. Säule) an. Beim endgültigen Verlassen der Schweiz können sie das Kapital des obligatorischen Teils beanspruchen (Freizügigkeitsleistung). Der überobligatorische Teil geht auf ein Freizügigkeitskonto.',
 'tfr.diffFrontaliereText2': 'Sie verlieren kein "TFR", weil TFR in der Schweiz nicht existiert — die 2. Säule ist der äquivalente Mechanismus, oft mit höheren Beträgen als das italienische TFR.',
 'tfr.faqTitle': 'Häufig gestellte Fragen',
 'tfr.faq1Q': 'Verliere ich TFR, wenn ich in der Schweiz arbeite?',
 'tfr.faq1A': 'Nein, denn in der Schweiz gibt es kein TFR. Stattdessen gibt es die 2. Säule (BVG/LPP), eine obligatorische berufliche Vorsorge. Beiträge werden bei der Pensionskasse Ihres Arbeitgebers gehalten und als Rente oder Kapital bei der Pensionierung oder beim endgültigen Verlassen der Schweiz zurückgezahlt.',
 'tfr.faq2Q': 'Kann ich die 2. Säule zurückerhalten, wenn ich nach Italien zurückkehre?',
 'tfr.faq2A': 'Ja. Wenn Sie die Schweiz endgültig verlassen, können Sie den obligatorischen Teil der 2. Säule beanspruchen. Der überobligatorische Teil wird auf ein Freizügigkeitskonto übertragen. Bei Rückkehr in ein EU/EFTA-Land bleibt der obligatorische Teil bis zur Pensionierung gesperrt; der überobligatorische Teil kann bar ausgezahlt werden.',
 'tfr.faq3Q': 'Ist die Schweizer 2. Säule vorteilhafter als das italienische TFR?',
 'tfr.faq3A': 'Es hängt von Gehalt, Alter und Beschäftigungsdauer ab. Im Allgemeinen sammelt die 2. Säule für mittlere bis hohe Gehälter und lange Karrieren in der Schweiz mehr an als das italienische TFR, da die Beiträge prozentual höher sind (7-18% vs. 7,4% für TFR). Verwenden Sie den Simulator oben für Ihren spezifischen Fall.',
 'tfr.faq4Q': 'Wie wird das italienische TFR berechnet?',
 'tfr.faq4A': 'Das italienische TFR wird berechnet, indem das Brutto-Jahresgehalt (RAL) durch 13,5 geteilt wird. Die jährliche Rücklage wird mit der Formel aufgewertet: 1,5% fest + 75% der ISTAT-Inflation. Das TFR wird bei Beendigung des Arbeitsverhältnisses ausgezahlt (Kündigung, Entlassung, Pensionierung).',
 'tfr.faq5Q': 'Wie funktioniert die BVG-Berechnung für Grenzgänger?',
 'tfr.faq5A': 'BVG-Beiträge werden auf dem koordinierten Lohn berechnet (Bruttolohn minus Koordinationsabzug von CHF 26.460, bis maximal CHF 90.720). Der Satz variiert mit dem Alter: 7% (25-34), 10% (35-44), 15% (45-54), 18% (55-65). Der Beitrag wird gleichmässig zwischen Arbeitgeber und Arbeitnehmer aufgeteilt.',
 'tfr.relatedTitle': 'Verwandte Werkzeuge',
 'tfr.linkPension': 'Rentenplaner',
 'tfr.linkPillar3': '3. Säule Simulator',
 'tfr.linkPayslip': 'Lohnabrechnung Simulator',
 'tfr.disclaimer': 'Die Berechnungen sind indikativ und basieren auf den gesetzlichen Parametern 2026 (BVG-Satz 1,25%, Koordinationsabzug CHF 26.460). Für TFR wird die gesetzliche Formel verwendet (Brutto/13,5 + Aufwertung). Die Ergebnisse stellen keine Finanz- oder Vorsorgeberatung dar. Konsultieren Sie einen Experten für Ihre spezifische Situation.',

