 'seo.tfrCalculator.description': 'TFR-Rechner für Grenzgänger: in der Schweiz gibt es kein TFR, also vergleiche die zweite Säule BVG mit dem italienischen TFR über mehrere Jahre, mit FAQ.',
 'seo.permitQuiz.description': 'Interaktives Quiz für Grenzgänger: beantworte 8 Fragen zu deiner Situation und finde heraus, ob die B-Bewilligung (Wohnsitz) oder die G-Bewilligung passt.',
 'seo.tredicesima.description': 'Rechner für 13. und 14. Monatslohn für Grenzgänger: ermittle deinen Extralohn, indem du den Schweizer 13. Lohn mit der italienischen Tredicesima vergleichst.',
 'seo.weeklyDigest.description': 'Wöchentlicher Digest für Grenzgänger: jeden Montag der aktuelle CHF/EUR-Wechselkurs, ausgewählte Artikel, das Tool der Woche und neue Stellenangebote dabei.',
 'seo.toolOfWeek.description': 'Das Tool der Woche für Grenzgänger: jede Woche heben wir einen anderen Rechner oder Vergleich hervor, den du ausprobieren und teilen kannst. Jetzt entdecken.',
 'seo.feedback.description': 'Hilf uns, Frontaliere Ticino zu verbessern: melde einen Fehler oder schlage eine neue Funktion auf GitHub vor und gestalte den Steuersimulator für Grenzgänger.',
