 'seo.gamification.description': 'Gamification für Grenzgänger: sammle XP-Punkte beim Erkunden des Steuersimulators, erfülle Ziele und schalte Stufen frei, während du lernst und Spass hast.',
 'seo.privacy.description': 'Datenschutzerklärung von Frontaliere Ticino: Umgang mit personenbezogenen Daten, Cookies, Analytics und Nutzerrechte, konform mit DSGVO und Schweizer DSG.',
 'seo.petition.description': 'Petition zur Schwelle zwischen Gaggiolo und Stabio: Verkehrsmeldungen, offizielle Daten und die Forderung nach einer sicheren technischen Prüfung.',

 'petition.hero.title': 'Ein fliessenderer Grenzübergang in Stabio',
 'petition.evidence.weekdayLabel': 'Werktage',
 'petition.hero.subtitle': 'Jeden Morgen wird der Übergang zwischen Gaggiolo und Stabio zum Engpass. Wir bitten die Behörden, die Wirkung der Schwelle zu messen und sie zu entfernen oder abzusenken, wenn eine sichere Lösung möglich ist.',
 'petition.hero.meta': 'Stabio · Gaggiolo · tägliche Mobilität',
 'petition.hero.cta': 'Petition unterschreiben',
 'petition.notice': 'Die Meldungen zur Schwelle und zur zusätzlichen Fahrzeit stammen aus unserer redaktionellen Sammlung und ersetzen keine offizielle Messung. Bisher haben wir keine öffentliche Mitteilung gefunden, die Installation und Wirkung dokumentiert; deshalb fordern wir vor jeder Entscheidung transparente Daten.',
 'petition.evidence.title': 'Was bisher bekannt ist',
 'petition.evidence.weekday': '1.083 Fahrzeuge pro Stunde zwischen 05:00 und 06:00 an Werktagen',
 'petition.evidence.weekendLabel': 'Wochenende',
 'petition.evidence.weekend': '15.836 Fahrzeuge pro Tag am Samstag; 12.489 am Sonntag',
 'petition.evidence.reportsLabel': 'Lokale Meldungen',
 'petition.evidence.reports': 'Lokale Meldungen: mehr als 10 zusätzliche Minuten und Staus ab etwa 05:00',
 'petition.ask.title': 'Was wir fordern',
 'petition.ask.intro': 'Sicherheit geht vor. Eine verkehrsberuhigende Massnahme muss aber verhältnismässig, überprüfbar und mit dem tatsächlichen Verkehrsfluss an einem internationalen Übergang vereinbar sein.',
 'petition.ask.item1': 'Den technischen Grund, das Einbaudatum und die mit der Schwelle verbundenen Geschwindigkeitsbegrenzungen veröffentlichen.',
 'petition.ask.item2': 'Fahrzeiten und Staus vor und nach der Schwelle an Werktagen und Feiertagen mit vergleichbaren Daten messen.',
 'petition.ask.item3': 'Die Schwelle entfernen oder absenken, wenn die Daten eine unverhältnismässige Wirkung zeigen und die Sicherheit anders gewährleistet werden kann.',
 'petition.ask.safety': 'Wir fordern keine Abschaffung der Verkehrssicherheit. Wir fordern eine wirksame Lösung für Anwohner, Arbeitnehmer und Grenzquerende.',
 'petition.sources.title': 'Quellen und Kontext',
